package server

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"os/user"
	"path/filepath"
	"strconv"
	"strings"
	"time"

	"github.com/CybexBV/whombat/appliance/helper/internal/activator"
	"github.com/CybexBV/whombat/appliance/helper/internal/ops"
	"github.com/CybexBV/whombat/appliance/helper/pkg/trust"
	"github.com/CybexBV/whombat/appliance/helper/pkg/wifi"
)

// FileConfig is the helper's JSON configuration (generated by the Nix module, root-owned).
type FileConfig struct {
	ManagerUser          string `json:"managerUser"`
	DeviceFile           string `json:"deviceFile"`
	PinnedRoot           string `json:"pinnedRoot"`
	MirrorDir            string `json:"mirrorDir"`
	StagingDir           string `json:"stagingDir"`
	AssignmentPath       string `json:"assignmentPath"`
	NetworkCandidatesDir string `json:"networkCandidatesDir"`
	StateDir             string `json:"stateDir"`
	// MetadataDir: the helper's verified TUF cache; absent is <stateDir>/tuf (a box on the GitHub repository has one
	// of its own, ops.Config.MetadataDir).
	MetadataDir    string              `json:"metadataDir,omitempty"`
	IdleTimeoutSec int                 `json:"idleTimeoutSec"`
	Activator      string              `json:"activator"` // "nix" | "fake"
	Nix            activator.NixConfig `json:"nix"`
	RuntimeUser    string              `json:"runtimeUser"` // runs schema-check/migrate (MD-10)
	FakeRoot       string              `json:"fakeRoot"`
	FakeDBDir      string              `json:"fakeDbDir"`
	// Edition: "commercial" (or absent: an older image's configuration) or "community" (Whombat HE-58, UP-X27).
	Edition string `json:"edition"`
	// DefaultChannel: "" (no update channels: the edition decides) or the channel a box has until the owner changes it
	// (production or development; Whombat LNK-21, UP-X29).
	DefaultChannel string `json:"defaultChannel"`
	// Wifi: iwd for the Wi-Fi operations (NX-244); no dir: no Wi-Fi (no_wifi). Bus "" is the system bus's socket.
	Wifi struct {
		Dir string `json:"dir"`
		Bus string `json:"bus"`
	} `json:"wifi"`
}

// Device is /persist/identity/device.json written at provisioning.
type Device struct {
	DeviceID string `json:"deviceId"`
	Env      string `json:"env"`
}

// Loaded is a resolved configuration.
type Loaded struct {
	Ops        ops.Config
	ManagerUID uint32
	Idle       time.Duration
	Activator  activator.Activator
}

// Load reads and resolves a helper config file.
func Load(path string) (*Loaded, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	var fc FileConfig
	dec := json.NewDecoder(strings.NewReader(string(b)))
	dec.DisallowUnknownFields()
	if err := dec.Decode(&fc); err != nil {
		return nil, fmt.Errorf("helper config: %w", err)
	}
	db, err := os.ReadFile(fc.DeviceFile)
	if err != nil {
		return nil, fmt.Errorf("device file: %w", err)
	}
	var dev Device
	if err := json.Unmarshal(db, &dev); err != nil || dev.DeviceID == "" || dev.Env == "" {
		return nil, errors.New("device file invalid")
	}
	switch fc.Edition {
	case "", ops.EditionCommercial, ops.EditionCommunity:
	default:
		return nil, fmt.Errorf("helper config: unknown edition %q", fc.Edition)
	}
	if fc.DefaultChannel != "" && !trust.ValidChannel(fc.DefaultChannel) {
		return nil, fmt.Errorf("helper config: unknown channel %q", fc.DefaultChannel)
	}
	if fc.MetadataDir != "" && !filepath.IsAbs(fc.MetadataDir) {
		return nil, fmt.Errorf("helper config: metadataDir %q is not absolute", fc.MetadataDir)
	}
	uid, err := lookupUID(fc.ManagerUser)
	if err != nil {
		return nil, err
	}
	l := &Loaded{ManagerUID: uid, Idle: time.Duration(fc.IdleTimeoutSec) * time.Second, Ops: ops.Config{
		DeviceID: dev.DeviceID, Env: dev.Env, Edition: fc.Edition, DefaultChannel: fc.DefaultChannel, PinnedRootPath: fc.PinnedRoot, MirrorDir: fc.MirrorDir,
		StagingDir: fc.StagingDir, AssignmentPath: fc.AssignmentPath, NetworkCandidatesDir: fc.NetworkCandidatesDir,
		StateDir: fc.StateDir, MetadataDir: fc.MetadataDir,
	}}
	if fc.Wifi.Dir != "" {
		l.Ops.Wifi, l.Ops.WifiDir = &wifi.IWD{Bus: fc.Wifi.Bus, Dir: fc.Wifi.Dir}, fc.Wifi.Dir
	}
	switch fc.Activator {
	case "nix":
		if fc.RuntimeUser != "" {
			u, err := user.Lookup(fc.RuntimeUser)
			if err != nil {
				return nil, fmt.Errorf("runtime user: %w", err)
			}
			uid, _ := strconv.ParseUint(u.Uid, 10, 32)
			gid, _ := strconv.ParseUint(u.Gid, 10, 32)
			fc.Nix.RuntimeUID, fc.Nix.RuntimeGID = uint32(uid), uint32(gid)
		}
		l.Activator = activator.NewNix(fc.Nix, nil)
	case "fake":
		if dev.Env == "prod" {
			return nil, errors.New("the fake activator is not allowed in prod")
		}
		f, err := activator.NewFake(fc.FakeRoot, "")
		if err != nil {
			return nil, err
		}
		f.DBDir = fc.FakeDBDir
		l.Activator = f
	default:
		return nil, fmt.Errorf("unknown activator %q", fc.Activator)
	}
	return l, nil
}

func lookupUID(name string) (uint32, error) {
	if n, err := strconv.ParseUint(name, 10, 32); err == nil {
		return uint32(n), nil
	}
	u, err := user.Lookup(name)
	if err != nil {
		return 0, fmt.Errorf("manager user: %w", err)
	}
	n, err := strconv.ParseUint(u.Uid, 10, 32)
	return uint32(n), err
}
